firwmware error.

Reported-by: Alexander Potapenko <glider@google.com>
Reported-by: Sebastian Alba Vives <sebasjosue84@gmail.com>
Fixes: e799035609e1 ("crypto: ccp: Implement SEV_PEK_CSR ioctl command")
Cc: stable@vger.kernel.org
Signed-off-by: Sean Christopherson <seanjc@google.com>
Signed-off-by: Herbert Xu <herbert@gondor.apana.org.au>

Here is the root cause:
When the SEV_PEK_CSR firmware command fails (e.g., due to insufficient buffer size), the code copies the length returned by firmware (which may exceed the allocated kernel buffer) to userspace via the input struct, then attempts to copy a blob of that length from the kernel buffer to userspace, resulting in a slab-out-of-bounds read and potential data leak. The fix adds an early exit on error to prevent copying the blob when the command failed.

Here is the patch:

 static int sev_ioctl_do_pek_csr(struct sev_issue_cmd *argp, bool writable)
 {
 	struct sev_device *sev = psp_master->sev_data;
 	struct sev_user_data_pek_csr input;
 	bool shutdown_required = false;
 	struct sev_data_pek_csr data;
 	void __user *input_address;
 	void *blob = NULL;
 	int ret;

 	if (!writable)
 		return -EPERM;

 	if (copy_from_user(&input, (void __user *)argp->data, sizeof(input)))
 		return -EFAULT;

 	memset(&data, 0, sizeof(data));

 	/* userspace wants to query CSR length */
 	if (!input.address || !input.length)
 		goto cmd;

 	/* allocate a physically contiguous buffer to store the CSR blob */
 	input_address = (void __user *)input.address;
 	if (input.length > SEV_FW_BLOB_MAX_SIZE)
 		return -EFAULT;

 	blob = kzalloc(input.length, GFP_KERNEL);
 	if (!blob)
 		return -ENOMEM;

 	data.address = __psp_pa(blob);
 	data.len = input.length;

 cmd:
 	if (sev->sev_plat_status.state == SEV_STATE_UNINIT) {
 		ret = sev_move_to_init_state(argp, &shutdown_required);
 		if (ret)
 			goto e_free_blob;
 	}

 	ret = __sev_do_cmd_locked(SEV_CMD_PEK_CSR, &data, &argp->error);

-	 /* If we query the CSR length, FW responded with expected data. */
+	/*
+	 * Firmware will returns the length of the CSR blob (either the minimum
+	 * required length or the actual length written), return it to the user.
+	 */
 	input.length = data.len;

 	if (copy_to_user((void __user *)argp->data, &input, sizeof(input))) {
 		ret = -EFAULT;
 		goto e_free_blob;
 	}

+	if (ret || WARN_ON_ONCE(argp->error))
+		goto e_free_blob;
+
 	if (blob) {
 		if (copy_to_user(input_address, blob, input.length))
 			ret = -EFAULT;
 	}

 e_free_blob:
 	if (shutdown_required)
 		__sev_firmware_shutdown(sev, false);

 	kfree(blob);
 	return ret;
 }



